\label{thm:empirical-signature-concentration}
		Let
		\[
		\mathcal F=\{(F_1,r_1),\ldots,(F_K,r_K)\}
		\]
		be a fixed finite family of rooted motifs, and set
		\(
		s_{\max}=\max_{1\leq k\leq K}|V(F_k)|.
		\)
		Assume that \(n\geq s_{\max}\). Then there exists a constant \(C>0\), depending only on
		\(\mathcal F\), such that for every \(\delta\in(0,1)\), with probability at least
		\(1-\delta\),
		\begin{equation}
			\max_{1\leq i\leq n}
			\left\|
			\widehat\Phi_i^{\mathcal F}
			-
			\Phi_W^{\mathcal F}(U_i)
			\right\|_2
			\leq
			C
			\sqrt{
				\frac{\log(nK)+\log(1/\delta)}
				{n}
			}.
		\end{equation}
		In particular, if \(K\) is fixed, then
		\begin{equation}
			\max_{1\leq i\leq n}
			\left\|
			\widehat\Phi_i^{\mathcal F}
			-
			\Phi_W^{\mathcal F}(U_i)
			\right\|_2
			=
			O_{\mathbb P}
			\left(
			\sqrt{\frac{\log n}{n}}
			\right).
		\end{equation}
